#define main archived_cli_main
#include "../scatterAdd-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <string>
#include <iostream>
#include <iomanip>
#define GPUCHECK(x) do{auto e=(x);if(e!=cudaSuccess){std::cerr<<cudaGetErrorString(e)<<"\n";exit(3);}}while(0)
template<class T>std::vector<T>rb(const std::string&p){std::ifstream f(p,std::ios::binary|std::ios::ate);auto n=f.tellg();f.seekg(0);std::vector<T>x(size_t(n)/sizeof(T));f.read((char*)x.data(),n);return x;}
struct F{int n,o,v;std::vector<int>hi;std::vector<float>hs,init;int*idx;float*src,*out;};
void reset(F&f){std::vector<float>x(f.o*f.v+17,-8);std::copy(f.init.begin(),f.init.end(),x.begin());GPUCHECK(cudaMemcpy(f.out,x.data(),x.size()*4,cudaMemcpyHostToDevice));GPUCHECK(cudaDeviceSynchronize());}
void launch(F&f,int mode){dim3 threads(32,16);int blocks=f.n/8192+1;size_t bytes=4*(f.o*f.v+512);if(mode==1)scatterAdd_kernel<<<blocks,threads,bytes>>>(f.idx,f.src,f.out,f.n,f.o,f.v);else scatterAdd2_kernel<<<blocks,threads,bytes>>>(f.idx,f.src,f.out,f.n,f.o,f.v);GPUCHECK(cudaGetLastError());}
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):3;if(rep!=3)return 2;std::string root=std::string(__FILE__).substr(0,std::string(__FILE__).find_last_of('/'));auto input=rb<float>(root+"/fixture.bin");auto gold=rb<double>(root+"/expected_outputs.bin");size_t pos=1;std::vector<F>fs;for(int ci=0;ci<int(input[0]);ci++){F f;f.n=int(input[pos++]);f.o=int(input[pos++]);f.v=int(input[pos++]);for(int i=0;i<f.n;i++)f.hi.push_back(int(input[pos++]));f.hs=std::vector<float>(input.begin()+pos,input.begin()+pos+f.n*f.v);pos+=f.n*f.v;f.init=std::vector<float>(input.begin()+pos,input.begin()+pos+f.o*f.v);pos+=f.o*f.v;GPUCHECK(cudaMalloc(&f.idx,f.n*4));GPUCHECK(cudaMalloc(&f.src,f.n*f.v*4));GPUCHECK(cudaMalloc(&f.out,(f.o*f.v+17)*4));GPUCHECK(cudaMemcpy(f.idx,f.hi.data(),f.n*4,cudaMemcpyHostToDevice));GPUCHECK(cudaMemcpy(f.src,f.hs.data(),f.n*f.v*4,cudaMemcpyHostToDevice));fs.push_back(f);}for(auto&f:fs)for(int mode:{1,2}){reset(f);launch(f,mode);GPUCHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){std::vector<float>got;std::vector<double>times;double ce=0;for(auto&f:fs)for(int mode:{1,2}){reset(f);auto st=std::chrono::steady_clock::now();for(int i=0;i<rep;i++)launch(f,mode);GPUCHECK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep);std::vector<float>h(f.o*f.v+17),cpu=f.init;GPUCHECK(cudaMemcpy(h.data(),f.out,h.size()*4,cudaMemcpyDeviceToHost));for(int i=0;i<rep;i++)scatter_add_reference(f.n,f.v,cpu.data(),f.hi.data(),f.hs.data());for(size_t i=0;i<cpu.size();i++)ce=std::max(ce,std::abs(double(cpu[i])-h[i]));got.insert(got.end(),h.begin(),h.end());}
bool ok=got.size()==gold.size();double ma=0,sum=0;for(size_t i=0;i<got.size();i++){double e=std::abs(double(got[i])-gold[i]);ma=std::max(ma,e);ok &=std::isfinite(got[i])&&e==0;}ok &=ce==0;for(auto v:times)sum+=v;std::string file="output_trial"+std::to_string(trial)+".bin";std::ofstream out(file,std::ios::binary);out.write((char*)input.data(),input.size()*4);out.write((char*)got.data(),got.size()*4);out.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<sum<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<got.size()<<",\"max_abs_error\":"<<ma<<",\"max_rel_error\":0,\"source_CPU_max_abs_error\":"<<ce<<",\"timing_region\":\"sum10_shared_atomic_scatter_launchmeans\",\"jit_excluded\":true,\"internal_repeats\":"<<rep<<",\"per_path_times_seconds\":[";for(size_t i=0;i<times.size();i++){if(i)std::cout<<",";std::cout<<times[i];}std::cout<<"],\"output_artifact\":{\"path\":\""<<file<<"\",\"dtype\":\"float32\",\"count\":"<<input.size()+got.size()<<",\"byte_order\":\"little\"}}\n";}}
